import { test, expect } from '@playwright/test';

test.describe('Document Language Declaration', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/document-page');
  });

  test('should display document language in HTML tag when set', async ({ page }) => {
    // Set document language using getByRole
    const languageLabel = page.getByRole('heading', { name: /Document Language/i });
    await expect(languageLabel).toBeVisible();

    // Set language using getByRole
    const languageInput = page.getByLabel(/document language/i);
    await languageInput.fill('en-US');

    // Verify language is set in HTML tag
    const languageTag = page.getByText(/lang="en-US"/i);
    await expect(languageTag).toBeVisible();

    // Verify language is displayed in the page title
    const pageTitle = page.getByRole('heading', { name: /Document Title/i });
    await expect(pageTitle).toContainText('en-US');

    // Verify language is reflected in the page content
    const content = page.getByText(/Welcome to the document/i);
    await expect(content).toBeVisible();
  });

  test('should handle invalid language codes gracefully', async ({ page }) => {
    // Set invalid language using getByRole
    const languageInput = page.getByLabel(/document language/i);
    await languageInput.fill('invalid-lang');

    // Verify language tag is not set
    const languageTag = page.getByText(/lang="en-US"/i);
    await expect(languageTag).not.toBeVisible();

    // Verify default language is used
    const defaultLanguageTag = page.getByText(/lang="en"/i);
    await expect(defaultLanguageTag).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/Invalid language code/i);
    await expect(errorMessage).toBeVisible();

    // Verify page content is still accessible
    const content = page.getByText(/Welcome to the document/i);
    await expect(content).toBeVisible();
  });
});
